import com.project.system.service.*;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
public class RechargeVerificationIntegration{public static void main(String[]args){try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(WalletIdentityIntegration.Config.class)){JdbcTemplate db=c.getBean(JdbcTemplate.class);WalletService s=c.getBean(WalletService.class);db.update("delete from campus_person_identity where user_id=2");try{s.trade(2,"RECHARGE",BigDecimal.TEN,null,null,UUID.randomUUID().toString(),1);throw new AssertionError();}catch(IllegalArgumentException e){System.out.println("PASS missing identity blocks recharge");}try{s.completeVerification(2,"invalid","13800000000");throw new AssertionError();}catch(IllegalArgumentException e){System.out.println("PASS invalid identity rejected");}s.completeVerification(2,"11010519491231002X","13800000000");s.trade(2,"RECHARGE",BigDecimal.TEN,null,null,UUID.randomUUID().toString(),1);System.out.println("PASS completed verification allows recharge");try{s.completeVerification(2,"11010519491231002X","13800000000");throw new AssertionError();}catch(IllegalArgumentException e){System.out.println("PASS existing identity cannot be overwritten");}System.out.println("PASS TOTAL 4");}}}

